import os
import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/var/uploads'
ALLOWED_EXTENSIONS = {'.pdf', '.docx', '.xlsx', '.png', '.jpg'}

def validate_filename(filename):
    """Basic filename sanitization - strips directory traversal attempts"""
    # Remove any path separators
    clean = filename.replace('/', '').replace('\\', '')
    # Check extension whitelist
    _, ext = os.path.splitext(clean)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None
    return clean

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless mode"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = validate_filename(uploaded.filename)
    if not filename:
        return jsonify({'error': 'Invalid file type'}), 400

    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    # Get optional page range from user for selective conversion
    page_range = request.form.get('pages', 'all')

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to pdf:"{page_range}" --outdir /var/output {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=60,
            cwd='/var/output'
        )
        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'detail': result.stderr.decode()[:200]}), 500

        output_name = os.path.splitext(filename)[0] + '.pdf'
        return jsonify({'status': 'ok', 'output': f'/var/output/{output_name}'})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/metadata', methods=['POST'])
def extract_metadata():
    """Extract document metadata using exiftool"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = validate_filename(uploaded.filename)
    if not filename:
        return jsonify({'error': 'Invalid file type'}), 400

    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    try:
        result = subprocess.run(
            ['exiftool', '-json', input_path],
            capture_output=True,
            timeout=30
        )
        return jsonify({'metadata': result.stdout.decode()})
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/health')
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs('/var/output', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
